function finalV(u,a,t){ return u+a*t; }
function disp(u,a,t){ return u*t+0.5*a*t*t; }
function finalVFromS(u,a,s){ return Math.sqrt(u*u+2*a*s); }
function avgV(u,v){ return 0.5*(u+v); }
function dispFromUVT(u,v,t){ return 0.5*(u+v)*t; }
var EXPORTS={ finalV:finalV, disp:disp, finalVFromS:finalVFromS, avgV:avgV, dispFromUVT:dispFromUVT };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.KinematicsForgePure = EXPORTS; }
